using UnityEngine;using UnityEngine.Rendering.HighDefinition;using System;using System.Linq;using System.IO;
public static class ValidateMirrorRepair{public static string Main(){var scooter=UnityEngine.Object.FindFirstObjectByType<MotorollerController>();int checks=0;void Check(bool v,string m){if(!v)throw new Exception(m);checks++;}
foreach(string side in new[]{"LeftMirror","RightMirror"}){var parent=scooter.GetComponentsInChildren<Transform>().First(t=>t.name==side);Check(parent.childCount==3,"Separate stem/housing/glass");foreach(var filter in parent.GetComponentsInChildren<MeshFilter>()){var mesh=filter.sharedMesh;var bounds=mesh.bounds;bounds.Expand(.00001f);Check(mesh.vertices.All(v=>bounds.Contains(v)),"Bounds contain all vertices "+filter.name);var m=filter.GetComponent<Renderer>().sharedMaterial;Check(m.GetFloat("_DoubleSidedEnable")==1&&m.GetFloat("_CullMode")==0,"No backface culling "+filter.name);}}
var face=scooter.GetComponentsInChildren<Transform>().First(t=>t.name=="LeftMirror").Find("Glass");var mf=face.GetComponent<MeshFilter>();Vector3 center=face.GetComponent<Renderer>().bounds.center;Vector3 normal=face.TransformDirection(mf.sharedMesh.normals[0]).normalized;
var go=new GameObject("Mirror inspection camera"){hideFlags=HideFlags.HideAndDontSave};var camera=go.AddComponent<Camera>();camera.enabled=false;camera.useOcclusionCulling=false;go.AddComponent<HDAdditionalCameraData>();camera.fieldOfView=50;camera.nearClipPlane=.0005f;var rt=RenderTexture.GetTemporary(900,900,24);var old=RenderTexture.active;var image=new Texture2D(900,900,TextureFormat.RGB24,false);
try{foreach(bool inside in new[]{false,true}){go.transform.position=center+normal*(inside?-.03f:.27f);go.transform.rotation=Quaternion.LookRotation(inside?normal:-normal,scooter.transform.up);var planes=GeometryUtility.CalculateFrustumPlanes(camera);Check(GeometryUtility.TestPlanesAABB(planes,face.GetComponent<Renderer>().bounds),"Glass remains in frustum "+inside);camera.targetTexture=rt;camera.Render();camera.Render();RenderTexture.active=rt;image.ReadPixels(new Rect(0,0,900,900),0,0);image.Apply();File.WriteAllBytes("output/Motoroller/Mirror"+(inside?"Inside":"Outside")+".png",image.EncodeToPNG());}string result="PASS: "+checks+" mirror hierarchy/bounds/double-sided/frustum checks. Glass normal="+normal;File.WriteAllText("output/Motoroller/mirror-repair-validation.txt",result);return result;}
finally{camera.targetTexture=null;RenderTexture.active=old;RenderTexture.ReleaseTemporary(rt);UnityEngine.Object.DestroyImmediate(image);UnityEngine.Object.DestroyImmediate(go);}}
}



